const root=window.SITE_ROOT||'',D=window.CATALOG,$=s=>document.querySelector(s),asset=f=>`${root}assets/${f}`,url=p=>root+p.replace(/^\//,''),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={arrow:'M5 12h14m-6-6 6 6-6 6',easel:'m5 21 7-18 7 18M7 15h10M12 3v14M6 9h12',leaf:'M20 4C8 2 2 9 7 16s15 1 13-12ZM6 20 16 9',wood:'M5 3h14v18H5zM9 3c-4 7 6 8 1 18m5-18c-4 7 6 9 0 18',school:'M3 21h18M5 21V9l7-6 7 6v12M9 21v-6h6v6M10 10h4',box:'m3 7 9-4 9 4v10l-9 4-9-4Zm0 0 9 5 9-5M12 12v9',search:'m16 16 5 5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',check:'m5 12 4 4L19 6',certificate:'M14 3H6a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V9L14 3Zm0 0v6h6M8 14l2 2 5-5',basket:'M3 9h18l-2 11H5L3 9Zm4 0 5-6 5 6M9 13v3m6-3v3',phone:'M7 3 3 7c1 7 7 13 14 14l4-4-5-4-3 3-5-5 3-3Z',pin:'M19 10c0 6-7 11-7 11S5 16 5 10a7 7 0 1 1 14 0ZM15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',menu:'M3 6h18M3 12h18M3 18h18',plus:'M12 5v14M5 12h14',tools:'M4 4 20 20M15 3l6 6-6 6-6-6ZM3 15l6 6',art:'M4 4h16v13H4zM12 17v4m-5 0h10M8 13l3-4 3 2 3-4',mail:'M3 5h18v14H3zM3 5l9 8 9-8'};
const icon=(n,cl='')=>`<svg class="icon ${cl}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.easel}"/></svg>`;
let selection;try{selection=JSON.parse(localStorage.getItem('molberty-selection')||'{}')}catch{selection={}}
selection=migrateSelection(selection);
function money(value){return Number(value).toLocaleString('ru-RU')+' ₽'}
function categoryById(id){return D.categories.find(c=>c.id===id)}
function categoryByRole(role){return categoryById(D.categoryRoles[role])}
function categoryCrumbs(c,linked=true){return c.pathIds.map(id=>{const part=categoryById(id);return !linked&&id===c.id?esc(part.name):`<a href="${url(part.id+'/')}">${esc(part.name)}</a>`}).join('<span>/</span>')}
function categoryBranch(id,current){const c=categoryById(id),active=c.id===current?.id,inside=current?.pathIds.includes(c.id);const anchor=`<a href="${url(c.id+'/')}"${active?' class="active" aria-current="page"':''}>${esc(c.name)}</a>`;return c.childIds.length?`<details class="category-branch"${inside?' open':''}><summary>${anchor}<span class="branch-toggle" aria-hidden="true">+</span></summary><div class="category-children">${c.childIds.map(child=>categoryBranch(child,current)).join('')}</div></details>`:`<div class="category-leaf">${anchor}</div>`}
function productById(id){return D.products.find(p=>p.id===id)}
function optionValues(option){const values=option.values.map((v,index)=>({...v,index})).filter(v=>v.label.trim());return values.some(v=>v.mode==='absolute')?values.filter(v=>v.mode==='absolute'):values}
function optionLabel(v){let label=v.label.replace(/\s*[;:]\s*[+−-]?\s*\d[\d\s]*\s*(?:р(?:уб)?\.?|₽)?\s*$/i,'').replace(/\s+\d[\d\s]*\s*(?:р(?:уб)?\.?|₽)\s*$/i,'').trim();if(/^[+−-]?\s*\d+$/.test(label)&&v.mode==='delta')label='Добавить';if(/^[–—-]$/.test(label))label='Без дополнения';return label+(v.price!==null?' — '+(v.mode==='delta'?'+':'')+money(v.price):'')}
function defaultState(p){const state={tier:p.defaultTier||((p.wholesalePrice!==null||p.wholesaleOnly)?'wholesale':'retail'),indices:p.options.map(o=>optionValues(o)[0]?.index??0),quantity:1};state.quantity=minQuantity(p,state);return state}
function activeOptions(p,state){return p.options.map((o,index)=>({...o,index})).filter(o=>o.index!==p.priceOptionIndex&&(!o.priceTier||o.priceTier===state.tier))}
function unitPrice(p,state){let base=state.tier==='wholesale'?(p.wholesalePrice??p.retailPrice):p.retailPrice,delta=0;if(p.priceOptionIndex!==null){const values=p.options[p.priceOptionIndex].values;const tierValue=values.find(v=>state.tier==='wholesale'?/опт/i.test(v.label):/розниц/i.test(v.label));if(tierValue?.price!==null&&tierValue?.price!==undefined)base=tierValue.price}for(const o of activeOptions(p,state)){const v=o.values[state.indices[o.index]];if(v?.mode==='absolute')base=v.price;if(v?.mode==='delta')delta+=v.price}return base+delta}
function minQuantity(p,state){return Math.max(p.minimumOrder||1,state.tier==='wholesale'?(p.wholesaleMin||1):1)}
function isFrom(p,state){return state.tier==='wholesale'||p.retailFrom}
function stateOptions(p,state){return activeOptions(p,state).map(o=>{const v=o.values[state.indices[o.index]];return o.name+': '+optionLabel(v)}).join('; ')}
function lineKey(p,state){return p.id+'_'+state.tier+'_'+state.indices.join('-')}
function migrateSelection(raw){const migrated={};if(!raw||typeof raw!=='object'||Array.isArray(raw))return migrated;for(const [key,value] of Object.entries(raw)){const previousId=typeof value==='number'?key:value?.productId;const id=D.legacyIdMap[previousId]||previousId;const p=productById(id);if(!p)continue;const state=defaultState(p);if(typeof value==='number'&&!p.wholesaleOnly)state.tier='retail';if(value&&typeof value==='object'){if(value.tier==='retail'&&!p.wholesaleOnly)state.tier='retail';else if(value.tier==='wholesale'&&(p.wholesalePrice!==null||p.wholesaleOnly))state.tier='wholesale';state.indices=p.options.map((o,i)=>optionValues(o).some(v=>v.index===value.indices?.[i])?value.indices[i]:state.indices[i])}const n=typeof value==='number'?value:value.quantity;state.quantity=Math.min(999,Math.max(minQuantity(p,state),Math.floor(Number(n)||1)));migrated[lineKey(p,state)]={productId:p.id,...state}}return migrated}
function selectedCount(){return Object.values(selection).reduce((n,line)=>n+line.quantity,0)}
function updateCartCounts(){const count=selectedCount();document.querySelectorAll('[data-count]').forEach(node=>node.textContent=count);const cart=$('[data-mobile-cart]');if(cart){cart.disabled=false;cart.setAttribute('aria-label',count?'Открыть корзину, изделий: '+count:'Открыть корзину');const badge=cart.querySelector('[data-mobile-count]');badge.textContent=count>99?'99+':count;badge.hidden=count===0}}
function save(){localStorage.setItem('molberty-selection',JSON.stringify(selection));updateCartCounts()}
function productMaterial(p){return p.material||p.features?.materials?.join(', ')||''}
function card(p){const material=productMaterial(p);return `<article class="product-card" data-product-id="${p.id}" data-price="${p.listingPrice}"><a class="product-img source-photo" href="${url('product/'+p.id+'/')}"><img src="${asset(p.image)}" alt="${esc(p.name)}" title="${esc(p.name)}" loading="lazy" width="420" height="440">${p.isNew?'<span class="new-badge">Новинка</span>':''}</a><div class="product-card-body">${material?`<div class="product-meta">${esc(material)}</div>`:''}<div class="text-h3 product-title"><a href="${url('product/'+p.id+'/')}">${esc(p.name)}</a></div><p>${esc(p.size)}</p><div class="product-bottom"><strong class="card-price">От ${money(p.listingPrice)}</strong><span class="price-unit">за шт.</span></div><div class="card-price-note">${p.defaultTier==='wholesale'?'Оптовая цена от '+p.defaultQuantity+' шт.':'Розничная цена'}</div><div class="card-actions"><button class="btn" data-quick="${p.id}" data-order-preview>Заказать</button><button class="quick-button" data-quick="${p.id}" aria-label="Быстрый просмотр: ${esc(p.name)}">Быстрый просмотр</button></div></div></article>`}
function gallery(p){return `<div class="product-gallery" data-gallery="${p.id}"><button class="product-main-image source-photo" data-image="${p.image}" data-gallery-id="${p.id}" data-gallery-index="0" data-caption="${esc(p.name)}" aria-label="Увеличить: ${esc(p.name)}"><img src="${asset(p.image)}" alt="${esc(p.name)}" title="${esc(p.name)}" width="640" height="680"><span class="zoom-hint">${icon('search')} Увеличить</span></button><div class="gallery-thumbs" aria-label="Фотографии товара">${p.gallery.map((img,i)=>`<button data-thumb="${i}" aria-label="Фотография ${i+1} из ${p.gallery.length}" aria-pressed="${i===0}"><img src="${asset(img.file)}" alt="${esc(p.name)} — ракурс ${i+1}" title="${esc(p.name)} — ракурс ${i+1}" width="100" height="100" loading="lazy"></button>`).join('')}</div></div>`}
function configurator(p){return `<div class="configurator" data-config="${p.id}"></div>`}
function configControls(p,state){const wholesale=p.wholesalePrice!==null;return `<label>Выберите цену<select data-tier>${!p.wholesaleOnly?'<option value="retail"'+(state.tier==='retail'?' selected':'')+'>Розница</option>':''}${wholesale||p.wholesaleOnly?'<option value="wholesale"'+(state.tier==='wholesale'?' selected':'')+'>Оптовая цена от '+(p.wholesaleMin||p.minimumOrder)+' шт.</option>':''}</select></label>${activeOptions(p,state).map(o=>`<label>${esc(o.name.replace(/\s*\((розница|опт[^)]*)\)/i,''))}<select data-option="${o.index}">${optionValues(o).map(v=>`<option value="${v.index}"${v.index===state.indices[o.index]?' selected':''}>${esc(optionLabel(v))}</option>`).join('')}</select></label>`).join('')}<div class="config-price" aria-live="polite"><strong data-unit-price></strong><span>за 1 шт.</span></div><div class="config-order-row"><label class="quantity-label">Количество<input type="number" data-config-qty min="${minQuantity(p,state)}" max="999" value="${state.quantity}" inputmode="numeric"></label><div class="config-total">Стоимость изделий<strong data-config-total></strong></div></div><p class="quantity-note" data-min-note></p><div class="detail-actions"><button class="btn order-button" data-order>Заказать ${icon('basket')}</button><button class="btn btn-outline" data-request="${esc(p.name)}">Задать вопрос</button></div><p class="quiet-note">Доставка рассчитывается отдельно. Наличие и срок изготовления согласуем при оформлении.</p>`}
function initConfigurator(host){const p=productById(host.dataset.config);host._state=defaultState(p);renderConfig(host,p);host.addEventListener('change',e=>{const state=host._state;if(e.target.matches('[data-tier]')){const before=activeOptions(p,state).find(o=>o.priceTier);const current=before?.values[state.indices[before.index]];state.tier=e.target.value;const after=activeOptions(p,state).find(o=>o.priceTier);if(after&&current){const dimension=v=>v.label.replace(/;.*$/,'').replace(/\s+\d+р.*$/,'').trim();const match=optionValues(after).find(v=>dimension(v)===dimension(current));if(match)state.indices[after.index]=match.index}state.quantity=Math.max(state.quantity,minQuantity(p,state));renderConfig(host,p);host.querySelector('[data-tier]').focus()}else if(e.target.matches('[data-option]')){state.indices[Number(e.target.dataset.option)]=Number(e.target.value);updateConfig(host,p)}else if(e.target.matches('[data-config-qty]')){const n=Number(e.target.value);if(!Number.isInteger(n)||n<minQuantity(p,state)||n>999){e.target.setCustomValidity('Минимальное количество: '+minQuantity(p,state)+' шт. Максимум: 999 шт.');e.target.reportValidity();return}e.target.setCustomValidity('');state.quantity=n;updateConfig(host,p)}});host.addEventListener('input',e=>{if(e.target.matches('[data-config-qty]')){e.target.setCustomValidity('');const n=Number(e.target.value);if(Number.isInteger(n)&&n>=minQuantity(p,host._state)&&n<=999){host._state.quantity=n;updateConfig(host,p)}}});host.addEventListener('click',e=>{if(!e.target.closest('[data-order]'))return;const qty=host.querySelector('[data-config-qty]');const n=Number(qty.value);if(!Number.isInteger(n)||n<minQuantity(p,host._state)||n>999){qty.setCustomValidity('Укажите количество от '+minQuantity(p,host._state)+' до 999');qty.reportValidity();return}host._state.quantity=n;const key=lineKey(p,host._state);selection[key]={productId:p.id,...host._state,indices:[...host._state.indices],quantity:Math.min(999,(selection[key]?.quantity||0)+n)};save();showSelection()})}
function renderConfig(host,p){host.innerHTML=configControls(p,host._state);updateConfig(host,p)}
function updateConfig(host,p){const state=host._state,price=unitPrice(p,state),prefix=isFrom(p,state)?'От ':'';host.querySelector('[data-unit-price]').textContent=prefix+money(price);host.querySelector('[data-config-total]').textContent=prefix+money(price*state.quantity);host.querySelector('[data-min-note]').textContent=minQuantity(p,state)>1?'Минимальный заказ в выбранном варианте — '+minQuantity(p,state)+' шт.':'';if(!host.closest('#request-dialog')){const schema=$('#product-schema');if(schema){const json=JSON.parse(schema.textContent);json.offers={'@type':isFrom(p,state)?'AggregateOffer':'Offer',url:json.url,priceCurrency:'RUB',[isFrom(p,state)?'lowPrice':'price']:price,seller:json.offers.seller};if(minQuantity(p,state)>1)json.offers.eligibleQuantity={'@type':'QuantitativeValue',minValue:minQuantity(p,state)};schema.textContent=JSON.stringify(json)}}}
function product(id){const p=productById(id),cat=D.categories.find(c=>c.id===p.primaryCategoryId);if(window.SITE_PRERENDER||!$('#product h1'))$('#product').innerHTML=`<section class="wrap">${bread(`<a href="${url('catalog/')}">Каталог</a><span>/</span>${categoryCrumbs(cat)}<span>/</span>${esc(p.name)}`)}<div class="product-detail">${gallery(p)}<div class="product-info">${eyebrow('Производство','КАТАЛОГ МОЛЬБЕРТЫ.РУ')}${p.isNew?'<span class="new-badge inline-badge">Новинка</span>':''}<h1>${esc(p.name)}</h1>${productMaterial(p)?`<p class="detail-material">${esc(productMaterial(p))}</p>`:''}${configurator(p)}<a class="text-link" href="${url('delivery/')}">Доставка и оплата ${icon('arrow')}</a></div></div><section class="product-description"><h2>Описание и характеристики</h2><div>${p.descriptionHtml}</div></section></section><section class="wrap section">${plainHeading('Ещё варианты','ВАША МАСТЕРСКАЯ','Другие модели<br> <em>из каталога.</em>')}<div class="product-grid">${D.products.filter(x=>x.id!==p.id&&x.categories.includes(cat.id)).concat(D.products.filter(x=>x.id!==p.id&&!x.categories.includes(cat.id))).slice(0,4).map(card).join('')}</div></section>${cta()}`;initConfigurator($('#product [data-config]'))}
function quickView(id){const p=productById(id);openDialog(`<div class="quick-view">${gallery(p)}<div class="quick-info">${p.isNew?'<span class="new-badge inline-badge">Новинка</span>':''}<h2>${esc(p.name)}</h2>${configurator(p)}<a class="text-link" href="${url('product/'+p.id+'/')}">Полное описание и характеристики ${icon('arrow')}</a></div></div>`,true);initConfigurator(dialog.querySelector('[data-config]'))}
function selectionText(deliveryNote='Доставка рассчитывается отдельно.'){return Object.values(selection).map(line=>{const p=productById(line.productId);return p.name+'\n'+(line.tier==='wholesale'?'Опт':'Розница')+'; '+stateOptions(p,line)+'\n'+line.quantity+' шт. × '+(isFrom(p,line)?'от ':'')+money(unitPrice(p,line))+' = '+(isFrom(p,line)?'от ':'')+money(unitPrice(p,line)*line.quantity)}).join('\n\n')+(selectedCount()?'\n\nИтого за изделия: '+(cartFrom()?'от ':'')+money(cartTotal())+'\n'+deliveryNote:'')}
function cartTotal(){return Object.values(selection).reduce((sum,line)=>sum+unitPrice(productById(line.productId),line)*line.quantity,0)}
function cartFrom(){return Object.values(selection).some(line=>isFrom(productById(line.productId),line))}
function cartSummary(){return `<span>Итого за изделия</span><strong>${cartFrom()?'от ':''}${money(cartTotal())}</strong><small>Доставка рассчитывается отдельно</small>`}
function showSelection(){openDialog(`${eyebrow('Ваш заказ','КОРЗИНА')}<h2>Ваша корзина</h2><div class="selection-list">${Object.entries(selection).map(([key,line])=>{const p=productById(line.productId);return `<div class="selection-row"><img src="${asset(p.image)}" alt="${esc(p.name)}" title="${esc(p.name)}" width="64" height="70"><div><a href="${url('product/'+p.id+'/')}">${esc(p.name)}</a><small>${line.tier==='wholesale'?'Оптовая цена':'Розница'} · ${isFrom(p,line)?'от ':''}${money(unitPrice(p,line))} / шт.</small><small>${esc(stateOptions(p,line))}</small></div><label><span class="sr-only">Количество: ${esc(p.name)}</span><input type="number" min="${minQuantity(p,line)}" max="999" value="${line.quantity}" data-qty="${key}"></label><button data-remove="${key}" aria-label="Удалить: ${esc(p.name)}">×</button><strong class="line-total" data-line-total="${key}">${isFrom(p,line)?'от ':''}${money(unitPrice(p,line)*line.quantity)}</strong></div>`}).join('')||`<p>Выберите изделия и комплектацию в каталоге.</p>${link('Перейти в каталог','catalog/')}`}</div>${selectedCount()?`<div class="cart-summary" id="cart-summary">${cartSummary()}</div><div class="dialog-actions"><button class="btn" data-checkout>Оформить заказ ${icon('arrow')}</button>${btn('Скачать заказ','data-download="selection"',true)}</div><p class="quiet-note">Подготовим письмо с составом заказа производителю. Подтвердим заказ после согласования наличия, сроков и доставки.</p>`:''}`,true)}
function changeCartQuantity(input){const line=selection[input.dataset.qty],p=productById(line.productId),value=Number(input.value);if(!Number.isInteger(value)||value<minQuantity(p,line)||value>999){input.value=line.quantity;toast('Минимальное количество — '+minQuantity(p,line)+' шт.');return}line.quantity=value;save();input.closest('.selection-row').querySelector('[data-line-total]').textContent=(isFrom(p,line)?'от ':'')+money(unitPrice(p,line)*value);$('#cart-summary').innerHTML=cartSummary()}
function changeThumbnail(button){const container=button.closest('[data-gallery]'),p=productById(container.dataset.gallery),index=Number(button.dataset.thumb),main=container.querySelector('[data-image]');main.dataset.image=p.gallery[index].file;main.dataset.galleryIndex=index;main.querySelector('img').src=asset(p.gallery[index].file);container.querySelectorAll('[data-thumb]').forEach(t=>t.setAttribute('aria-pressed',t===button));}
