function interiorGuide(){
 const steps=[
  ['01','Измеряйте размер картины.','Измерьте ширину и высоту работы вместе с рамой. Для панно или фотографии без рамы укажите полный внешний размер. Эти габариты нужны, чтобы сопоставить работу с размерами мольберта.'],
  ['02','Подумайте над высотой размещения работы.','Определите, на какой высоте от пола должен находиться нижний край картины. Оцените, как работа будет смотреться рядом с мебелью и с привычной точки обзора. Высота самого мольберта и высота его лотка — разные параметры.'],
  ['03','Выберите модель мольберта.','Сравните внешний вид, габариты и глубину лотка. Для картины в объёмной раме важны место на опоре и способ фиксации. Вес учитывайте вместе с рамой и стеклом — допустимую нагрузку согласуем перед заказом.'],
  ['04','Согласуйте детали.','Передайте размеры картины, её вес, глубину рамы и желаемую высоту размещения. Обсудим модель, материал, отделку и крепление, проверим комплектацию и условия доставки.']
 ];
 return `<section class="interior-guide reading" id="interior-guide" aria-labelledby="interior-guide-title"><div class="eyebrow"><span>Руководство</span> ДЛЯ ВАШЕЙ ЭКСПОЗИЦИИ</div><h2 id="interior-guide-title">Мольберт для Вашей картины.</h2><p class="lead">Для дорогих Вам произведений — картин, панно, фотографий.</p>${steps.map(([n,title,text])=>`<article class="guide-step"><span aria-hidden="true">${n}</span><div><h3 class="text-h2">${title}</h3><p>${text}</p></div></article>`).join('')}<div class="interior-guide-choice">${icon('art')}<div><div class="text-h3">Три вопроса о Вашей картине</div><p>Габариты картины, высота экспозиции, вес и глубина рамы.</p></div>${btn('Подобрать по трём вопросам','data-interior-quiz disabled')}</div><noscript><p>Для подбора сообщите параметры картины по телефону <a href="tel:+79258809539">+7 (925) 880-95-39</a>.</p></noscript></section>`;
}

function categoryGuideText(step){
 let text=esc(step.text||'');
 for(const [label,id] of step.links||[]){const product=productById(id);if(product)text=text.replace(esc(label),`<a href="${url('product/'+id+'/')}" title="${esc(product.name)}">${esc(label)}</a>`);}
 return text;
}
function categoryGuide(c){
 const guide=window.CATEGORY_GUIDES?.[c?.id];if(!guide)return '';
 return `${guide.summaryTitle?`<div class="category-guide-summary"><h2>${esc(guide.summaryTitle)}</h2><p>${esc(c.description)}</p></div>`:''}<section class="category-guide reading" id="category-guide" aria-labelledby="category-guide-title"><div class="eyebrow"><span>Советы</span> ПЕРЕД ВЫБОРОМ</div><h2 id="category-guide-title">${esc(guide.title)}</h2>${guide.subtitle?`<p class="lead">${esc(guide.subtitle)}</p>`:''}${guide.steps.map((step,index)=>`<article class="guide-step"><span aria-hidden="true">${String(index+1).padStart(2,'0')}</span><div><h3 class="text-h2">${esc(step.title)}</h3>${step.text?`<p>${categoryGuideText(step)}</p>`:''}</div></article>`).join('')}<div class="category-guide-action"><p>Обсудим размеры, комплектацию и условия заказа.</p>${btn('Согласовать детали',`data-request="${esc('Подбор: '+c.name+'. '+guide.title)}"`)}</div></section>`;
}
function categoryDescription(c){
 if(c?.role==='interiors')return interiorGuide();
 if(window.CATEGORY_GUIDES?.[c?.id])return categoryGuide(c);
 return (c?.seo?`<h2>${esc(c.seo.title)}</h2>${c.seo.paragraphs.map(p=>`<p>${esc(p)}</p>`).join('')}`:`<h2>${c?esc(c.name):'Выбираем оборудование осознанно'}</h2><p>${c?esc(c.description):'Подбирайте мольберт по рабочему формату, устойчивости основания и возможности хранения.'}</p><p>Перед заказом согласуем комплектацию и условия получения. Для нестандартной задачи можно прислать размерный эскиз.</p>`)+link('Руководство по выбору','guide/',true);
}

function catalog(categoryId){
const c=categoryById(categoryId),host=c?$('#category'):$('#catalog'),base=c?D.products.filter(p=>p.categories.includes(c.id)):D.products,children=c?c.childIds:D.categoryRoots;
const materials=[...new Set(base.flatMap(p=>p.features.materials))].sort((a,b)=>a.localeCompare(b,'ru'));
const filters=c?.filters||['material','shelf','double'];
if(window.SITE_PRERENDER||!host.querySelector('#catalog-results'))host.innerHTML=`<section class="wrap page-intro ${c?'category-intro':''}">${bread(c?`<a href="${url('catalog/')}">Каталог</a><span>/</span>${categoryCrumbs(c,false)}`:'Каталог')}${eyebrow('Каталог','СОБСТВЕННОЕ ПРОИЗВОДСТВО')}<h1>${c?esc(c.name):'Каталог мольбертов и оборудования'}</h1><p>${c?esc(c.description):'Мольберты и оборудование из натурального дерева. Для вашей техники, пространства и следующей идеи.'}</p></section><section class="wrap catalog-layout"><!--noindex--><aside class="sidebar"><div class="text-h2 sidebar-title">Категории</div><a href="${url('catalog/')}" class="${!c?'active':''}"${!c?' aria-current="page"':''}>Весь каталог</a><nav class="category-tree" aria-label="Разделы каталога">${D.categoryRoots.map(id=>categoryBranch(id,c)).join('')}</nav><div class="sidebar-help">${icon('easel')}<div class="text-h3">Сложно выбрать?</div>${window.CATEGORY_GUIDES?.[c?.id]?'<p>Ориентиры для Вашего выбора.</p><a href="#category-guide">Читать руководство ↘</a>':`<p>Начните с трёх вопросов.</p><button ${c?.role==='interiors'?'data-interior-quiz disabled':'data-quiz'}>Помочь с выбором ↗</button>`}</div></aside><!--/noindex--><div class="catalog-main">${children.length?`<nav class="subcategory-grid" aria-label="${c?'Подразделы '+esc(c.name):'Основные разделы'}">${children.map(id=>{const sub=categoryById(id);return `<a href="${url(sub.id+'/')}"><strong>${esc(sub.name)}</strong><span>${esc(sub.description)}</span></a>`}).join('')}</nav>`:''}<div class="catalog-toolbar"><label class="search-field">${icon('search')}<input id="catalog-search" type="search" placeholder="Название или задача" aria-label="Поиск по каталогу"></label><label><span class="sr-only">Материал</span><select id="material"><option value="">Все материалы</option>${materials.map(m=>`<option value="${esc(m)}">${esc(m)}</option>`).join('')}</select></label><label><span class="sr-only">Сортировка</span><select id="sort"><option value="default">По умолчанию</option><option value="name">По названию А–Я</option><option value="price-asc">Сначала дешевле</option><option value="price-desc">Сначала дороже</option></select></label></div><div class="catalog-feature-filters">${filters.includes('shelf')&&base.some(p=>p.features.shelf)?`<label>Полка<select id="shelf"><option value="">Все варианты</option><option value="included">Есть в комплекте</option><option value="optional">Дополнительная полка</option></select></label>`:''}${filters.includes('double')&&base.some(p=>p.features.sidedness==='double')?`<label>Рабочие стороны<select id="sidedness"><option value="">Все варианты</option><option value="double">Двусторонние</option></select></label>`:''}</div><div class="results-line"><button id="reset-filters">Сбросить фильтры</button></div><div id="catalog-results" class="product-grid" aria-live="polite"></div><p class="quiet-note">Указаны цены за единицу. Стоимость выбранной комплектации и партии рассчитывается в карточке товара.</p><div class="category-description">${categoryDescription(c)}</div></div></section>${documentsSection()}${cta()}`;
function filter(){const q=$('#catalog-search').value.trim().toLocaleLowerCase('ru'),m=$('#material').value,shelf=$('#shelf')?.value,sides=$('#sidedness')?.value;let items=base.filter(p=>(p.name+' '+p.description+' '+p.material).toLocaleLowerCase('ru').includes(q)&&(!m||p.features.materials.includes(m))&&(!shelf||p.features.shelf===shelf)&&(!sides||p.features.sidedness===sides));if($('#sort').value==='name')items.sort((a,b)=>a.name.localeCompare(b.name,'ru'));if($('#sort').value==='price-asc')items.sort((a,b)=>a.listingPrice-b.listingPrice);if($('#sort').value==='price-desc')items.sort((a,b)=>b.listingPrice-a.listingPrice);$('#catalog-results').innerHTML=items.length?items.map(card).join(''):`<div class="empty"><h3>По вашему запросу ничего не найдено</h3><p>Попробуйте другое название или сбросьте фильтры.</p></div>`}
$('#catalog-search').addEventListener('input',filter);for(const selector of ['#material','#sort','#shelf','#sidedness'])$(selector)?.addEventListener('change',filter);$('#reset-filters').onclick=()=>{$('#catalog-search').value='';$('#material').value='';$('#sort').value='default';if($('#shelf'))$('#shelf').value='';if($('#sidedness'))$('#sidedness').value='';filter()};if(!$('#catalog-results').children.length||$('#catalog-search').value||$('#material').value||$('#sort').value!=='default'||$('#shelf')?.value||$('#sidedness')?.value)filter();
}
function standard(id,title,body){if(!window.SITE_PRERENDER&&$('#'+id+' h1'))return;$('#'+id).innerHTML=`<section class="wrap page-intro">${bread(title)}${eyebrow('Мольберты.ру','ПРОИЗВОДСТВО С 1991 ГОДА')}<h1>${title}</h1></section>${body}${cta()}`}
function pages(){
if($('#about'))standard('about','Собственное производство.<br> <em>С 1991 года.</em>',`<section class="wrap editorial"><img src="${asset('workshop.webp')}" alt="Визуализация ручной столярной работы" width="1200" height="800"><div><h2>Производим мольберты и оборудование</h2><p>На собственном производстве работаем с натуральным деревом и создаём оборудование для творческих пространств: мольберты, мебель для изостудий и предметы интерьера.</p><p>Основа подхода — классические технологии деревообработки. Машинная точность сочетается с ручной доводкой, чтобы готовое изделие сохраняло красоту материала.</p><h3>Стандарты и комплектация</h3><p class="production-compliance">${esc(D.production.compliance)}</p><h3>Ремесло, которому учатся</h3><p>В 1993–1999 годах сотрудники мастерской проходили профессиональную подготовку в Германии в рамках совместного ремесленного образовательного проекта.</p><p>В 2003 году Палата ремёсел Москвы выдала диплом мастера столяра-ремесленника. Этот опыт лежит в основе ежедневной работы на производстве.</p><h3>От мольберта до предмета мебели</h3><p>Кроме оборудования для художников, изготавливаем индивидуальную мебель и реплики исторических предметов. Нестандартный проект начинается с разговора и эскиза.</p><p class="quiet-note">Изображение мастерской — авторская визуализация.</p></div></section>`);
if($('#documents'))standard('documents',D.businessDocuments.title,businessDocumentsBody());
if($('#contacts'))standard('contacts','Контакты',contactsPageBody());
if($('#guide'))standard('guide','Мольберт под вашу руку.',`<section class="wrap reading"><p class="lead">Хороший мольберт начинается с ваших привычек: где вы рисуете, какой формат любите и сколько места есть в мастерской.</p>${[['01','Определите рабочий формат','Измерьте самый большой холст или планшет. Высота всего мольберта и предельная высота холста — разные параметры. Проверьте оба перед заказом.'],['02','Выберите конструкцию','Лира — классическая тренога. Хлопушка даёт готовую плоскость для бумаги. Станковый мольберт подходит для устойчивой работы с крупными форматами. Настольный экономит место.'],['03','Подумайте о технике','Для акварели может понадобиться горизонтальная поверхность — обратите внимание на трансформеры. Для живописи важны наклон холста и положение верхнего фиксатора.'],['04','Проверьте пространство','Измерьте рабочую зону и место для хранения. У складных моделей уточните глубину в сложенном состоянии. Не забудьте оставить место для движения перед холстом.'],['05','Согласуйте детали','Полка, ящик, планшет или колёсные опоры зависят от модели. Обсудите комплектацию, материал и размеры с мастером.']].map(([n,t,s])=>`<article class="guide-step"><span>${n}</span><div><h2>${t}</h2><p>${s}</p></div></article>`).join('')}${btn('Подобрать по трём вопросам','data-quiz')}</section>`);
if($('#delivery'))standard('delivery','Доставка и оплата заказа',deliveryPageBody());
if($('#privacy'))legalPage('privacy');
if($('#consent'))legalPage('consent');
}

function legalPage(id){
 const host=$('#'+id),page=window.LEGAL_PAGES?.[id];
 if(!host||!page||(!window.SITE_PRERENDER&&host.querySelector('h1')))return;
 const controls=id==='privacy'?`<a class="text-link" href="${url('consent/')}">Соглашение на обработку персональных данных</a><button type="button" class="text-link" data-clear>Удалить сохранённые данные</button>`:`<a class="text-link" href="${url('privacy/')}">Политика конфиденциальности</a>`;
 host.innerHTML=`<section class="wrap page-intro legal-intro">${bread(esc(page.title))}${eyebrow('Мольберты.ру','ДОКУМЕНТЫ')}<h1>${esc(page.title)}</h1></section><section class="wrap reading legal-document">${page.html}<div class="legal-actions">${controls}</div></section>`;
}

const dialog=$('#request-dialog');function presentModal(modal){if(window.siteMotion)window.siteMotion.openDialog(modal);else if(!modal.open)modal.showModal()}function dismissModal(modal){if(window.siteMotion)window.siteMotion.closeDialog(modal);else modal.close()}function openDialog(content,wide=false){dialog.classList.toggle('wide-dialog',wide);$('#dialog-content').innerHTML=content;presentModal(dialog)}function closeDialog(){dismissModal(dialog)}function toast(t){$('#toast').textContent=t;$('#toast').classList.add('visible');setTimeout(()=>$('#toast').classList.remove('visible'),2500)}
function formConsent(){return `<label class="form-consent"><input type="checkbox" name="personal_data_consent" value="yes" required><span>Нажимая кнопку, вы соглашаетесь с <a href="${url('privacy/')}" target="_blank" rel="noopener">политикой конфиденциальности</a> и даёте <a href="${url('consent/')}" target="_blank" rel="noopener">согласие на обработку персональных данных</a>.</span></label>`}
function request(subject='',isOrder=false){if(isOrder){checkoutRequest();return}let draft={};try{draft=JSON.parse(localStorage.getItem('molberty-draft')||'{}')}catch{};openDialog(`${eyebrow('Напишите производителю','ВАША ИДЕЯ')}<h2>${isOrder?'Оформить заказ':'Начнём с разговора.'}</h2><p>Подготовьте запрос и отправьте его на почту производителя.</p><form id="request-form"><label>Как к вам обращаться<input name="name" autocomplete="name" required maxlength="100" value="${esc(draft.name||'')}" placeholder="Ваше имя"></label><label>Контакт для ответа<input name="contact" autocomplete="email" required maxlength="160" value="${esc(draft.contact||'')}" placeholder="Телефон или электронная почта"></label><label>О вашей задаче<textarea name="message" rows="4" maxlength="20000" placeholder="Что хотите создать? Формат, количество, размеры…">${esc(isOrder?selectionText():subject?subject+'\n'+selectionText():draft.message||selectionText())}</textarea></label><p class="quiet-note">Данные сохранятся только в этом браузере. На следующем шаге вы сможете открыть письмо или скачать запрос.</p>${formConsent()}<button class="btn" type="submit">Подготовить письмо ${icon('arrow')}</button></form>`);$('#request-form').onsubmit=e=>{e.preventDefault();if(!e.target.reportValidity())return;const {name,contact,message}=Object.fromEntries(new FormData(e.target)),values={name,contact,message};localStorage.setItem('molberty-draft',JSON.stringify(values));const body=`Здравствуйте!\n\n${values.message}\n\nИмя: ${values.name}\nКонтакт: ${values.contact}`;storeRequest=body;openDialog(`${eyebrow('Готово к отправке','ВАШ ЗАПРОС')}<h2>Осталось отправить.</h2><p>Запрос подготовлен, но ещё не отправлен производителю. Откройте письмо в почтовом приложении или скачайте текст и отправьте на <a href="mailto:molberty@gmail.com">molberty@gmail.com</a>.</p><pre class="request-preview">${esc(body)}</pre><div class="dialog-actions"><a class="btn" href="mailto:molberty@gmail.com?subject=${encodeURIComponent('Запрос с сайта Мольберты.ру')}&body=${encodeURIComponent(body)}">Открыть письмо ${icon('mail')}</a>${btn('Скачать запрос','data-download="request"',true)}</div>`)};}
const checkoutMethods=[
 {value:'moscow',label:'Доставка по Москве'},
 {value:'regions',label:'Доставка в регионы'},
 {value:'pickup',label:'Самовывоз — бесплатно'}
];
function checkoutShippingNote(method){return method==='pickup'?'Самовывоз — бесплатно.':'Стоимость доставки рассчитывается отдельно.'}
function checkoutSummary(method=''){
 return `<section class="checkout-summary" aria-labelledby="checkout-summary-title"><div class="checkout-summary-heading"><h3 id="checkout-summary-title">Состав заказа</h3><button type="button" class="text-link" data-selection>Изменить</button></div><div class="checkout-items">${Object.values(selection).map(line=>{
  const p=productById(line.productId),options=stateOptions(p,line),price=unitPrice(p,line),prefix=isFrom(p,line)?'от ':'';
  return `<article class="checkout-item"><a class="checkout-item-image" href="${url('product/'+p.id+'/')}" aria-label="${esc(p.name)}"><img src="${asset(p.image)}" alt="${esc(p.name)}" title="${esc(p.name)}" width="80" height="96" loading="lazy"></a><div class="checkout-item-info"><a href="${url('product/'+p.id+'/')}">${esc(p.name)}</a><small>${line.tier==='wholesale'?'Оптовая цена':'Розница'}${options?' · '+esc(options):''}</small><span>${line.quantity} шт. × ${prefix}${money(price)}</span></div><strong class="checkout-line-total">${prefix}${money(price*line.quantity)}</strong></article>`;
 }).join('')}</div><div class="cart-summary checkout-total" aria-live="polite"><span>Итого за изделия</span><strong data-checkout-total>${cartFrom()?'от ':''}${money(cartTotal())}</strong><small data-checkout-shipping-note>${checkoutShippingNote(method)}</small></div></section>`;
}
function readCheckoutDraft(){
 const read=key=>{try{const value=JSON.parse(localStorage.getItem(key)||'{}');return value&&typeof value==='object'&&!Array.isArray(value)?value:{}}catch{return {}}};
 const saved=read('molberty-checkout-draft'),legacy=read('molberty-draft'),contact=typeof legacy.contact==='string'?legacy.contact:'';
 const value=(key,fallback='',max=100)=>typeof saved[key]==='string'?saved[key].slice(0,max):typeof fallback==='string'?fallback.slice(0,max):'';
 return {name:value('name',legacy.name),phone:value('phone',contact.includes('@')?'':contact,40),email:value('email',contact.includes('@')?contact:'',160),city:value('city'),address:value('address','',300),delivery:checkoutMethods.some(m=>m.value===saved.delivery)?saved.delivery:''};
}
function checkoutValues(form){
 const values={};for(const key of ['name','phone','email','city','address'])values[key]=form.elements.namedItem(key).value.trim();
 values.delivery=form.querySelector('[name="delivery"]:checked')?.value||'';return values;
}
function saveCheckoutDraft(values){try{localStorage.setItem('molberty-checkout-draft',JSON.stringify(values))}catch{}}
function checkoutReview(values,body){
 const method=checkoutMethods.find(m=>m.value===values.delivery),details=[['Имя',values.name],['Телефон',values.phone],['Электронная почта',values.email||'—'],['Получение',method.label]];
 if(values.delivery!=='pickup')details.push(['Город',values.city],['Адрес доставки',values.address]);
 storeRequest=body;
 openDialog(`${eyebrow('Ваш заказ','ГОТОВО К ОТПРАВКЕ')}<h2>Заказ подготовлен</h2><p>Проверьте данные и откройте письмо в почтовом приложении или скачайте заказ для отправки производителю.</p><div class="checkout-review"><div><dl class="checkout-review-details">${details.map(([label,value])=>`<div><dt>${label}</dt><dd>${esc(value)}</dd></div>`).join('')}</dl><button class="text-link" type="button" data-checkout>Изменить контакты и доставку</button></div>${checkoutSummary(values.delivery)}</div><div class="dialog-actions"><a class="btn" href="mailto:molberty@gmail.com?subject=${encodeURIComponent('Заказ с сайта Мольберты.ру')}&body=${encodeURIComponent(body)}">Открыть письмо ${icon('mail')}</a>${btn('Скачать заказ','data-download="order"',true)}</div>`,true);
}
function checkoutRequest(){
 if(!selectedCount()){showSelection();return}
 const draft=readCheckoutDraft();
 openDialog(`${eyebrow('Ваш заказ','ОФОРМЛЕНИЕ')}<h2>Оформить заказ</h2><form id="request-form" class="checkout-form"><div class="checkout-layout"><div class="checkout-fields"><fieldset class="checkout-fieldset"><legend>Контактные данные</legend><label>Как к вам обращаться<input name="name" autocomplete="name" required maxlength="100" value="${esc(draft.name)}" placeholder="Ваше имя"></label><label>Телефон<input name="phone" type="tel" autocomplete="tel" inputmode="tel" required minlength="7" maxlength="40" value="${esc(draft.phone)}" placeholder="+7 (___) ___-__-__"></label><label>Электронная почта (e-mail)<input name="email" type="email" autocomplete="email" maxlength="160" value="${esc(draft.email)}" placeholder="example@mail.ru"></label></fieldset><fieldset class="checkout-fieldset checkout-delivery" aria-describedby="checkout-delivery-help checkout-delivery-note"><legend>Способ получения</legend><p class="checkout-field-note" id="checkout-delivery-help">Выберите один вариант.</p>${checkoutMethods.map(method=>`<label class="delivery-choice"><input type="checkbox" name="delivery" value="${method.value}"${draft.delivery===method.value?' checked':''}><span>${method.label}</span></label>`).join('')}<p class="checkout-field-note" id="checkout-delivery-note">Стоимость доставки варьируется от вашего адреса, региона и способа доставки. Доставку согласуем при оформлении заказа.</p></fieldset><div class="checkout-address"><label>Укажите город<input name="city" autocomplete="address-level2" maxlength="100" value="${esc(draft.city)}" placeholder="Город получения заказа"></label><label>Укажите адрес доставки<input name="address" autocomplete="street-address" maxlength="300" value="${esc(draft.address)}" placeholder="Улица, дом, офис или квартира"></label></div></div>${checkoutSummary(draft.delivery)}</div><p class="quiet-note">Подготовим письмо с заказом: вы сможете проверить его и отправить производителю.</p>${formConsent()}<button class="btn checkout-submit" type="submit">Подготовить письмо ${icon('arrow')}</button></form>`,true);
 const form=$('#request-form'),choices=[...form.querySelectorAll('[name="delivery"]')],phone=form.elements.namedItem('phone');
 function syncDelivery(changed){
  if(changed?.checked)for(const choice of choices)if(choice!==changed)choice.checked=false;
  for(const choice of choices)choice.setCustomValidity('');
  const method=form.querySelector('[name="delivery"]:checked')?.value||'',pickup=method==='pickup';
  form.querySelector('.checkout-address').hidden=pickup;
  for(const key of ['city','address']){const input=form.elements.namedItem(key);input.disabled=pickup;input.required=!!method&&!pickup}
  form.querySelector('[data-checkout-shipping-note]').textContent=checkoutShippingNote(method);
 }
 syncDelivery();
 form.addEventListener('input',event=>{if(event.target===phone)phone.setCustomValidity('');if(!event.target.matches('[type="checkbox"]'))saveCheckoutDraft(checkoutValues(form))});
 form.addEventListener('change',event=>{if(event.target.matches('[name="delivery"]'))syncDelivery(event.target);saveCheckoutDraft(checkoutValues(form))});
 form.onsubmit=event=>{
  event.preventDefault();const values=checkoutValues(form),digits=values.phone.replace(/\D/g,'');
  phone.setCustomValidity(digits.length>=7&&digits.length<=20?'':'Укажите телефон с кодом города или оператора.');
  choices[0].setCustomValidity(values.delivery?'':'Выберите способ получения заказа.');
  if(!form.reportValidity())return;
  saveCheckoutDraft(values);
  const method=checkoutMethods.find(m=>m.value===values.delivery),contacts=['Имя: '+values.name,'Телефон: '+values.phone];
  if(values.email)contacts.push('Электронная почта: '+values.email);
  const shipping=['Способ получения: '+method.label];
  if(values.delivery!=='pickup')shipping.push('Город: '+values.city,'Адрес доставки: '+values.address);
  const body='Здравствуйте!\n\nПрошу оформить заказ.\n\n'+contacts.join('\n')+'\n\n'+shipping.join('\n')+'\n\nСостав заказа\n'+selectionText(checkoutShippingNote(values.delivery));
  checkoutReview(values,body);
 };
}

function callbackRequest(){request('Прошу перезвонить.');$('#dialog-content h2').textContent='Заказать звонок';$('#dialog-content>p').textContent='Укажите телефон и удобное время для звонка. Подготовим письмо производителю.';const contact=$('#request-form [name="contact"]');contact.closest('label').firstChild.textContent='Ваш телефон';contact.type='tel';contact.autocomplete='tel';contact.placeholder='+7 (___) ___-__-__';$('#request-form [name="message"]').value='Прошу перезвонить. Удобное время: ';$('#request-form [name="name"]').focus()}
let storeRequest='';function download(name,text,type='text/plain;charset=utf-8'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff'+text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000)}
let quizState={step:0,answers:[]};const quizQuestions=[['Где будете работать?',['Дома','В художественной студии','На выставке']],['Какой формат вам ближе?',['Небольшой, на столе','Обычный холст или планшет','Большие полотна']],['Что особенно важно?',['Компактное хранение','Устойчивое основание','Менять наклон поверхности']]];
function quiz(reset=true){if(reset)quizState={step:0,answers:[]};const s=quizState.step;if(s===3){const role=quizState.answers[0]===2?'exhibitions':quizState.answers[1]===0?'artists/desktop':quizState.answers[2]===2||quizState.answers[1]===2||quizState.answers[2]===1?'artists/floor/professional':'artists/floor/lira';const c=categoryByRole(role);openDialog(`${eyebrow('Результат','ВАША ОТПРАВНАЯ ТОЧКА')}<h2>Присмотритесь:<br> <em>${c.name.toLowerCase()}.</em></h2><p>${c.description}</p><p>Подбор ориентировочный. Перед заказом уточните допустимый формат, размеры и комплектацию.</p>${link('Посмотреть варианты',c.id+'/')}<div class="dialog-actions">${btn('Обсудить с мастером',`data-request="Подбор: ${c.name}"`,true)}<button class="text-link" data-quiz>Пройти ещё раз</button></div>`);return}const [title,answers]=quizQuestions[s];openDialog(`${eyebrow(`Шаг ${s+1} из 3`,'ПОДБИРАЕМ МОЛЬБЕРТ')}<div class="quiz-progress"><span style="width:${(s+1)/3*100}%"></span></div><h2>${title}</h2><div class="quiz-options">${answers.map((v,i)=>`<button data-answer="${i}"><span>0${i+1}</span>${v}${icon('arrow')}</button>`).join('')}</div>${s?'<button class="text-link" data-back>← Назад</button>':''}`)}
document.addEventListener('click',e=>{let t=e.target.closest('button,a');if(!t)return;if(t.matches('[data-close]'))closeDialog();if(t.matches('[data-selection],[data-mobile-cart]'))showSelection();if(t.matches('[data-request]'))request(t.dataset.request||'');if(t.matches('[data-callback]'))callbackRequest();if(t.matches('[data-quiz]'))quiz();if(t.matches('[data-answer]')){quizState.answers[quizState.step]=Number(t.dataset.answer);quizState.step++;quiz(false)}if(t.matches('[data-back]')){quizState.step--;quiz(false)}if(t.matches('[data-quick]'))quickView(t.dataset.quick);if(t.matches('[data-checkout]'))request('',true);if(t.matches('[data-thumb]'))changeThumbnail(t);if(t.matches('[data-top]'))window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});if(t.matches('[data-remove]')){delete selection[t.dataset.remove];save();showSelection()}if(t.matches('[data-clear]')){localStorage.removeItem('molberty-draft');localStorage.removeItem('molberty-checkout-draft');window.siteCookies?.reset();selection={};save();toast('Сохранённые данные удалены')}if(t.matches('[data-download]')){const type=t.dataset.download;if(type==='selection')download('molberty-zakaz.txt','Заказ оборудования\n\n'+selectionText());if(type==='request'||type==='order')download(type==='order'?'molberty-zakaz.txt':'molberty-zapros.txt',storeRequest);if(type==='checklist')download('chek-list-masterskoy.txt','ЧЕК-ЛИСТ МАСТЕРСКОЙ\n\n□ Количество рабочих мест\n□ Возраст и рост учеников\n□ Максимальный формат планшета/холста\n□ Работа стоя или сидя\n□ Нужен ли горизонтальный наклон\n□ Размеры помещения и проходы\n□ Место для хранения\n□ Свет для постановки натюрморта\n□ Подставки для рисунков\n□ Дата и способ получения\n\nПодготовлено Мольберты.ру\nЭтот список не является нормативным техническим заданием.');if(type==='spec')download('spisok-oborudovaniya.csv','Наименование;Количество;Материал;Рабочий формат;Примечание\nМольберт;;;;\nСтол для натюрморта;;;;\nПодставка для рисунков;;;;\nРабочая мебель;;;;','text/csv;charset=utf-8')}if(t.matches('.mobile-menu')){const open=t.getAttribute('aria-expanded')!=='true';t.setAttribute('aria-expanded',open);$('.header nav').classList.toggle('open',open)}});
document.addEventListener('change',e=>{if(e.target.matches('[data-qty]'))changeCartQuantity(e.target)});
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog()}});
if($('#not-found'))notFound();if($('#home')&&(window.SITE_PRERENDER||!$('#home h1')))home();if($('#catalog'))catalog();if($('#category'))catalog($('#category').dataset.id);if($('#product'))product($('#product').dataset.id);pages();

function articleCard(a){const p=a.presentation||{};return `<article class="blog-card"><a class="blog-card-image themed-article-image" href="${url('blog/'+a.id+'/')}"><img src="${asset(p.previewImage||a.image)}" alt="${esc(p.previewAlt||a.title)}" title="${esc(a.title)}" loading="lazy" width="${p.previewWidth||a.imageWidth||600}" height="${p.previewHeight||a.imageHeight||400}"></a><div class="article-meta"><span>${esc(a.topic)}</span><span>${p.readingMinutes||1} мин чтения</span></div><div class="text-h3"><a href="${url('blog/'+a.id+'/')}">${esc(a.title)}</a></div><p>${esc(p.excerpt||a.summary)}</p><a class="text-link" href="${url('blog/'+a.id+'/')}">Читать статью ${icon('arrow')}</a></article>`}
function blogPreview(){return `<section class="wrap section blog-preview">${plainHeading('Блог','ПУБЛИКАЦИИ ПРОИЗВОДИТЕЛЯ','О мольбертах.<br> <em>С пониманием ремесла.</em>',`<a class="text-link" href="${url('blog/')}">Все публикации ${icon('arrow')}</a>`)}<div class="blog-grid">${D.articles.map(articleCard).join('')}</div></section>`}
function blog(){const host=$('#blog');if(!window.SITE_PRERENDER&&host.querySelector('h1'))return;host.innerHTML=`<section class="wrap page-intro">${bread('Блог')}${eyebrow('О нашем производстве','СТАТЬИ И ПУБЛИКАЦИИ')}<h1>Статьи и публикации</h1><p>Здесь Вы можете познакомиться с нашими публикациями в прессе.</p></section><section class="wrap blog-section"><div class="blog-grid">${D.articles.map(articleCard).join('')}</div><a class="blog-guide" href="${url('blog/kak-vybrat-molbert/')}"><span>${icon('easel')}</span><div>${eyebrow('Практическое руководство','ПЕРЕД ПОКУПКОЙ')}<h2>Как выбрать свой мольберт</h2><p>От формата холста и техники — к удобной конструкции.</p></div>${icon('arrow')}</a></section>${cta()}`}
// Split long original paragraphs at sentence boundaries, retaining inline markup and every character.
function readableParagraphs(html){const source=document.createElement('div');source.innerHTML=html;const walker=document.createTreeWalker(source,NodeFilter.SHOW_TEXT),nodes=[];let node,offset=0;while((node=walker.nextNode())){nodes.push({node,start:offset,end:offset+node.textContent.length});offset+=node.textContent.length}if(!nodes.length)return html;const text=source.textContent,cuts=[0];for(const match of text.matchAll(/[.!?](?:[»”"])?\s+(?=[А-ЯЁ«])/gu)){const cut=match.index+match[0].length;if(cut-cuts[cuts.length-1]>=340&&text.length-cut>=140)cuts.push(cut)}cuts.push(text.length);function boundary(pos){const found=nodes.find(n=>pos<=n.end)||nodes[nodes.length-1];return[found.node,Math.max(0,Math.min(found.node.textContent.length,pos-found.start))]}return cuts.slice(0,-1).map((start,i)=>{const range=document.createRange();range.setStart(...boundary(start));range.setEnd(...boundary(cuts[i+1]));const paragraph=document.createElement('p');paragraph.append(range.cloneContents());return paragraph.outerHTML}).join('')}
function articleBlock(block,index,presentation={}){if(block.type==='image'&&presentation.imageOverrides?.[index])return `<figure class="article-original-figure" data-source-index="${index}">${articleModelImages(presentation.imageOverrides[index].productIds)}</figure>`;if(block.type==='heading'){const tag=block.level===3?'h3':'h2';return `<${tag}>${esc(block.text)}</${tag}>`}if(block.type==='image')return `<figure class="article-original-figure" data-source-index="${index}"><button class="article-image-button" data-image="${esc(block.file)}" data-caption="${esc(block.caption||block.alt||'')}" aria-label="Увеличить изображение"><img src="${asset(block.file)}" alt="${esc(block.alt||'')}" title="${esc(block.caption||block.alt||'')}" width="${block.width||1000}" height="${block.height||750}" loading="lazy"></button>${block.caption?`<figcaption>${esc(block.caption)}</figcaption>`:''}</figure>`;const highlight=presentation.highlights?.includes(index);return `<div class="article-original-paragraph${highlight?' article-highlight':''}" data-source-index="${index}">${readableParagraphs(block.html||esc(block.text||''))}</div>`}
function articleSections(a){const p=a.presentation,blocks=a.blocks||[];if(!p?.sections?.length)return blocks.map((b,i)=>articleBlock(b,i,p)).join('');return p.sections.map((section,n)=>{let body='';for(let i=section.start;i<section.end;i++){const list=p.listRanges?.find(([start])=>start===i);if(list){body+='<ul class="article-feature-list">';for(let j=i;j<Math.min(list[1],section.end);j++)body+=`<li class="article-original-paragraph" data-source-index="${j}">${blocks[j].html||esc(blocks[j].text)}</li>`;body+='</ul>';i=list[1]-1}else body+=articleBlock(blocks[i],i,p)}return `<section class="article-chapter" id="${section.id}" tabindex="-1"><div class="chapter-label">${String(n+1).padStart(2,'0')}</div><h2>${esc(section.title)}</h2>${body}${section.productIds?articleModelImages(section.productIds):''}</section>`}).join('')}
function observeArticleContents(){const sections=document.querySelectorAll('.article-chapter');if(!sections.length)return;const links=[...document.querySelectorAll('.article-contents a')];function mark(id){links.forEach(a=>{if(a.hash==='#'+id)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current')})}links.forEach(a=>a.addEventListener('click',()=>mark(a.hash.slice(1))));mark(sections[0].id);if('IntersectionObserver' in window){const observer=new IntersectionObserver(entries=>{const visible=entries.filter(e=>e.isIntersecting).sort((a,b)=>a.boundingClientRect.top-b.boundingClientRect.top);if(visible.length)mark(visible[0].target.id)},{rootMargin:'-165px 0px -55% 0px',threshold:0});sections.forEach(section=>observer.observe(section))}}
function article(id){if(!window.SITE_PRERENDER&&$('#article h1')){observeArticleContents();return}const a=D.articles.find(x=>x.id===id);if(!a)return;const p=a.presentation||{};$('#article').innerHTML=`<article><header class="wrap page-intro article-intro">${bread(`<a href="${url('blog/')}">Блог</a><span>/</span>${esc(a.title)}`)}${eyebrow(a.topic,'СТАТЬЯ')}<h1>${esc(a.title)}</h1>${a.summary?`<div class="article-lead">${a.introHtml||esc(a.summary)}</div>`:''}<div class="article-publication"><span class="article-read-time">${p.readingMinutes||1} мин чтения</span>${a.publication?`<span>${esc(a.publication)}</span>`:''}</div></header>${p.previewImage?`<div class="wrap article-hero-cover"><img src="${asset(p.previewImage)}" alt="${esc(p.previewAlt)}" title="${esc(a.title)}" width="${p.previewWidth}" height="${p.previewHeight}" fetchpriority="high"></div>`:''}<div class="wrap article-layout"><aside class="article-toc"><details class="article-contents" open><summary>Содержание статьи<span aria-hidden="true">−</span></summary><nav aria-label="Содержание статьи">${(p.sections||[]).map((section,i)=>`<a href="#${section.id}"><span>${String(i+1).padStart(2,'0')}</span>${esc(section.title)}</a>`).join('')}</nav></details><a class="text-link article-back-link" href="${url('blog/')}">← Все публикации</a></aside><div class="article-text article-original-body">${articleSections(a)}${a.originalAuthor?`<p class="article-original-author">${esc(a.originalAuthor)}</p>`:''}</div></div></article><section class="wrap section related-articles">${heading('Продолжить чтение','БЛОГ ПРОИЗВОДИТЕЛЯ','Ещё немного<br> <em>о любимом деле.</em>')}<div class="blog-grid">${D.articles.filter(x=>x.id!==a.id).map(articleCard).join('')}</div></section>${cta()}`;observeArticleContents()}
if($('#blog'))blog();if($('#article'))article($('#article').dataset.id);

function clientLogoStyle(client){return client.logo?.background?` style="background:${esc(client.logo.background)}"`:''}
function clientMark(client){return client.logo?`<img src="${asset(client.logo.file)}" alt="${esc(client.name)}" title="${esc(client.name)}" loading="lazy" width="${client.logo.width}" height="${client.logo.height}">`:`<span class="client-text-mark">${esc(client.shortName||client.name)}</span>`}
function reviewsSection(){const source=$('#reviews-data');if(!source)return '';const data=JSON.parse(source.textContent);return `<section class="wrap section reviews-home" id="reviews" aria-label="Демонстрационные отзывы организаций">${plainHeading('11','Отзывы','Для учебных классов.<br> <em>И больших задач.</em>','Подбор оборудования, комплектация учебных пространств и поставки для организаций.')}<div class="reviews-toolbar"><div class="reviews-controls" hidden><button type="button" class="reviews-arrow reviews-arrow-prev" data-reviews-prev aria-label="Предыдущие отзывы" aria-controls="reviews-track" disabled>${icon('arrow')}</button><button type="button" class="reviews-arrow" data-reviews-next aria-label="Следующие отзывы" aria-controls="reviews-track">${icon('arrow')}</button></div></div><div class="reviews-grid" id="reviews-track" tabindex="0" role="group" aria-label="Отзывы организаций, горизонтальная прокрутка">${data.items.map((review,index)=>`<figure class="review-card" aria-label="Отзыв ${index+1} из ${data.items.length}"><div class="review-card-top"><span class="review-sector">${esc(review.sector)}</span><span class="review-quote-mark" aria-hidden="true">“</span></div><div class="review-title">${esc(review.title)}</div><blockquote><p>${esc(review.text)}</p></blockquote><figcaption class="review-author"><img class="review-portrait" src="${asset(review.photo)}" alt="Сгенерированный портрет: ${esc(review.name)}" width="384" height="384" loading="lazy" decoding="async"><span><span class="review-author-name">${esc(review.name)}</span><span class="review-author-role">${esc(review.role)}</span></span></figcaption></figure>`).join('')}</div></section>`}
function clientsSection(){const directory=window.CLIENT_DIRECTORY;if(!directory)return '';const featured=directory.featuredIds.map(id=>directory.clients.find(c=>c.id===id)).filter(Boolean);return `<section class="clients-home" id="clients"><div class="wrap section">${plainHeading('10','Нас выбирают','Нам <em>доверяют.</em>','Работаем с университетами, художественными школами, музеями и организациями из разных городов России.')}<div class="client-logo-grid">${featured.map(c=>`<div class="client-logo-tile"${clientLogoStyle(c)} title="${esc(c.name)}">${clientMark(c)}</div>`).join('')}<a class="client-logo-tile client-logo-all" href="${url('clients/')}"><span>Все наши<br>клиенты</span>${icon('arrow')}</a></div></div></section>`}
function clientCard(c){return `<article class="client-card" id="${c.id}" data-client-id="${c.id}" data-client-group="${c.group}"><div class="client-card-logo"${clientLogoStyle(c)}>${clientMark(c)}</div><div class="client-card-body"><div class="client-card-name">${esc(c.name)}</div>${c.city?`<div class="client-card-city">${esc(c.city)}</div>`:''}${c.website&&c.websiteActive!==false?`<a class="client-card-site" href="${esc(c.website)}" target="_blank" rel="nofollow noopener noreferrer" aria-label="Официальный сайт: ${esc(c.name)}">Сайт организации ${icon('arrow')}</a>`:''}</div></article>`}
function clientsPage(){
 const host=$('#clients-page'),directory=window.CLIENT_DIRECTORY;if(!directory)return;
 if(window.SITE_PRERENDER||!host.querySelector('h1'))host.innerHTML=`<section class="wrap page-intro clients-intro">${bread('Наши клиенты')}${eyebrow('Сотрудничество','ПРОИЗВОДСТВО С 1991 ГОДА')}<h1>Наши клиенты</h1><p>Мольберты и оборудование нашего производства выбирают для обучения, творчества и выставок. Среди наших клиентов — университеты, художественные школы, музеи, театры и другие организации.</p></section><section class="wrap clients-directory" aria-label="Организации, с которыми мы работали"><div class="clients-tools" hidden><div class="clients-filters" role="group" aria-label="Направление деятельности"><button type="button" class="client-filter" data-client-filter="all" aria-pressed="true">Все клиенты</button>${Object.entries(directory.groups).map(([key,name])=>`<button type="button" class="client-filter" data-client-filter="${key}" aria-pressed="false">${esc(name)}</button>`).join('')}</div></div><div class="clients-grid">${directory.clients.map(clientCard).join('')}</div><p class="sr-only" data-client-status role="status" aria-live="polite"></p></section>${cta()}`;
 const filters=[...host.querySelectorAll('[data-client-filter]')],cards=[...host.querySelectorAll('[data-client-id]')];
 filters.forEach(button=>button.addEventListener('click',()=>{const group=button.dataset.clientFilter;let visible=0;for(const card of cards){card.hidden=group!=='all'&&card.dataset.clientGroup!==group;if(!card.hidden)visible++}filters.forEach(filter=>filter.setAttribute('aria-pressed',filter===button));host.querySelector('[data-client-status]').textContent='Показано организаций: '+visible}));
 if(!window.SITE_PRERENDER)host.querySelector('.clients-tools').hidden=false;
}
if($('#clients-page'))clientsPage();

