function documentsSection(){return `<div class="wrap documents-grid"><section class="price-section" id="price-list">${eyebrow('Документы','ПРАЙС-ЛИСТ')}${icon('download')}<div class="text-h2">Весь ассортимент.<br> <em>В одном документе.</em></div><p>Посмотрите модели и цены, чтобы собрать список оборудования для мастерской или учебного класса.</p><a class="btn" href="https://drive.google.com/file/d/1hdN3FlxO29hL8MQ5lMPjxcvcQ5jL37mf/view" target="_blank" rel="noopener">Открыть прайс-лист ${icon('arrow')}</a><span class="document-note">Документ откроется в Google Drive</span><a class="text-link price-local-link" href="${url('prices/')}">Посмотреть цены на сайте ${icon('arrow')}</a></section><section class="certificate-section" id="certificate"><div>${eyebrow('Качество','СЕРТИФИКАТ')}<div class="text-h2">Подтверждено<br> <em>документом.</em></div><p>Сертификат добровольного соответствия на изделия из древесины и древесных материалов.</p><p class="certificate-validity">Срок по документу:<br> <strong>09.04.2025 — 08.04.2028</strong></p><button class="text-link" data-image="documents/certificate.webp" data-caption="Сертификат добровольного соответствия Мольберты.ру" data-document="documents/certificate.pdf">Рассмотреть сертификат ${icon('search')}</button><a class="text-link document-pdf" href="${asset('documents/certificate.pdf')}" target="_blank" rel="noopener">Открыть PDF ↗</a></div><button class="certificate-preview" data-image="documents/certificate.webp" data-caption="Сертификат добровольного соответствия Мольберты.ру" data-document="documents/certificate.pdf" aria-label="Увеличить изображение сертификата"><img src="${asset('documents/certificate-preview.webp')}" alt="Сертификат соответствия Мольберты.ру — нажмите для увеличения" loading="lazy" width="450" height="637"><span>${icon('search')}</span></button></section></div>`}
function casesSection(){return `<section class="wrap section cases-section" id="cases">${plainHeading('11','Кейсы','Каким может стать<br> <em>ваше пространство.</em>','Три концепции оснащения: от учебного класса до камерной галереи.')}<div class="case-grid">${D.showcase.map(c=>`<article class="case-card"><button class="case-image" data-case="${c.id}" aria-label="Посмотреть концепцию ${c.name}"><img src="${asset(c.image)}" alt="Визуализация: ${c.name}" width="800" height="533" loading="lazy"><span class="concept-badge">Концепция · вымышленный объект</span></button><div class="case-card-body"><div class="case-meta"><span>${c.type}</span><span>${c.count}</span></div><div class="text-h3">${c.title}</div><p class="case-name">${c.name}</p><p>${c.description}</p><button class="text-link" data-case="${c.id}">Посмотреть концепцию ${icon('arrow')}</button></div></article>`).join('')}</div><p class="quiet-note">Названия объектов и изображения придуманы для этого варианта сайта. Это примеры решений, а не выполненные заказы.</p></section>`}
function partnersSection(){return `<section class="partner-showcase"><div class="wrap section">${heading('12','Творчество объединяет','От первой линии —<br> <em>до собственной выставки.</em>','Художественные школы, частные студии и галереи — пространства, для которых создаётся наше оборудование.')}<div class="partner-object-grid">${D.showcase.map(c=>`<button class="partner-object" data-case="${c.id}"><img src="${asset(c.image)}" alt="Концепция пространства: ${c.name}" loading="lazy" width="600" height="400"><span class="partner-object-info"><span class="partner-monogram">${c.initials}</span><span><strong>${c.name}</strong><small>${c.type}</small></span>${icon('arrow')}</span></button>`).join('')}</div><p class="quiet-note">Концепция блока партнёров. Представлены вымышленные организации и визуализации, а не список реальных клиентов.</p></div></section>`}
function contactsSection(){const address='Мытищи, Проектируемый проезд 4530, строение 2, СпецМашМонтаж';const map='https://yandex.ru/map-widget/v1/?ll=37.761421%2C55.939803&pt=37.761421%2C55.939803%2Cpm2gnm&z=16';return `<section class="wrap section home-contacts" id="home-contacts">${heading('Контакты','ДО ВСТРЕЧИ НА ПРОИЗВОДСТВЕ','Давайте обсудим<br> <em>ваш следующий замысел.</em>')}<div class="home-contacts-grid"><div class="home-contact-details"><h3>Связаться с производителем</h3><span class="contact-label">Розничные заказы</span><a href="tel:+79258809539">+7 (925) 880-95-39</a><span class="contact-label">Оптовые заказы</span><a href="tel:+79262119363">+7 (926) 211-93-63</a><a class="contact-email" href="mailto:molberty@gmail.com">molberty@gmail.com</a><div class="contact-address">${icon('pin')}<p>Московская область, г. Мытищи,<br> Проектируемый проезд 4530, строение 2.<br> Завод «СпецМашМонтаж».</p></div><p class="contact-visit">Перед визитом согласуйте время по телефону.</p><a class="btn btn-outline" target="_blank" rel="noopener" href="https://yandex.ru/maps/?text=${encodeURIComponent(address)}">Построить маршрут ${icon('arrow')}</a></div><div class="contact-map"><iframe src="${map}" title="Карта: производство Мольберты.ру в Мытищах, Проектируемый проезд 4530, строение 2" loading="lazy" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe><a href="https://yandex.ru/maps/?text=${encodeURIComponent(address)}" target="_blank" rel="noopener">Открыть адрес в Яндекс Картах ↗</a></div></div></section>`}
function showCase(id){const c=D.showcase.find(x=>x.id===id);if(!c)return;openDialog(`${eyebrow('Концепция','ВЫМЫШЛЕННЫЙ ОБЪЕКТ')}<h2>${c.name}</h2><img class="case-dialog-image" src="${asset(c.image)}" alt="Визуализация концепции ${c.name}" width="800" height="533"><p>${c.description}</p><ul class="case-equipment">${c.equipment.map(t=>`<li>${t}</li>`).join('')}</ul><p class="quiet-note">Демонстрационный проект с вымышленным названием и созданным изображением. Количество и состав оборудования показывают возможный сценарий оснащения.</p>${btn('Обсудить похожую задачу',`data-request="Оснащение по концепции: ${c.name}"`)}`)}
let viewerZoom=1;
function updateViewerZoom(){const img=$('#viewer-image');img.style.width=(viewerZoom*100)+'%';$('#image-dialog [data-zoom="reset"]').textContent=Math.round(viewerZoom*100)+'%';$('#image-dialog [data-zoom="out"]').disabled=viewerZoom<=0.5;$('#image-dialog [data-zoom="in"]').disabled=viewerZoom>=3}
function showImage(t){viewerZoom=1;const viewer=$('#image-dialog');viewer.dataset.galleryId=t.dataset.galleryId||'';viewer.dataset.galleryIndex=t.dataset.galleryIndex||'0';$('#viewer-image').src=asset(t.dataset.image);$('#viewer-image').alt=t.dataset.caption||'Просмотр изображения';$('#viewer-image').title=t.dataset.caption||'Просмотр изображения';$('#viewer-caption').textContent=t.dataset.caption||'';const doc=$('#viewer-document');doc.hidden=!t.dataset.document;if(t.dataset.document)doc.href=asset(t.dataset.document);let nav=viewer.querySelector('.viewer-gallery-nav');if(!nav){nav=document.createElement('div');nav.className='viewer-gallery-nav';nav.innerHTML='<button data-gallery-prev aria-label="Предыдущее фото">←</button><span data-gallery-count></span><button data-gallery-next aria-label="Следующее фото">→</button>';viewer.querySelector('.image-viewer-toolbar').prepend(nav)}const p=productById(viewer.dataset.galleryId);nav.hidden=!p||p.gallery.length<2;if(p)nav.querySelector('[data-gallery-count]').textContent=(Number(viewer.dataset.galleryIndex)+1)+' / '+p.gallery.length;updateViewerZoom();presentModal(viewer)}
function galleryStep(step){const viewer=$('#image-dialog'),p=productById(viewer.dataset.galleryId);if(!p)return;const index=(Number(viewer.dataset.galleryIndex)+step+p.gallery.length)%p.gallery.length;showImage({dataset:{image:p.gallery[index].file,caption:p.name,galleryId:p.id,galleryIndex:String(index)}})}
document.addEventListener('keydown',e=>{if(!$('#image-dialog').open)return;if(e.key==='ArrowLeft'){e.preventDefault();galleryStep(-1)}if(e.key==='ArrowRight'){e.preventDefault();galleryStep(1)}});
document.addEventListener('click',e=>{const t=e.target.closest('button,a');if(!t)return;if(t.matches('[data-case]'))showCase(t.dataset.case);if(t.matches('[data-image]'))showImage(t);if(t.matches('[data-gallery-prev]'))galleryStep(-1);if(t.matches('[data-gallery-next]'))galleryStep(1);if(t.matches('[data-image-close]'))dismissModal($('#image-dialog'));if(t.matches('[data-zoom]')){viewerZoom=t.dataset.zoom==='reset'?1:Math.max(.5,Math.min(3,viewerZoom+(t.dataset.zoom==='in'?.25:-.25)));updateViewerZoom()}if(t.closest('.header nav,#mobile-bottom-nav')){$('.header nav').classList.remove('open');$('.mobile-menu').setAttribute('aria-expanded','false')}});
$('#image-dialog').addEventListener('click',e=>{if(e.target===$('#image-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dismissModal(e.target)}});
function updateHeader(){const top=$('[data-top]');if(top)top.hidden=window.scrollY<500;const scrolled=window.scrollY>24;$('#header').classList.toggle('is-scrolled',scrolled)}
window.addEventListener('scroll',updateHeader,{passive:true});updateHeader();

function salesSections(){const sales=D.sales;return `<section class="wrap sales-sections"><div class="sales-grid"><article class="sales-card" id="wholesale"><div class="eyebrow"><span>Организациям</span> ОПТОВЫЕ ПРОДАЖИ</div><h2>Оптовые продажи</h2><a class="sales-phone" href="tel:+79262119363">${sales.wholesalePhone}</a><h3>Заявка и оплата</h3><p>${sales.wholesale.order}</p><p>${sales.wholesale.invoice}</p><p class="wholesale-proposals">${esc(sales.wholesale.competitiveProposals)}</p><h3>Поставка в регионы</h3><dl class="shipping-rates"><div><dt>Картонная упаковка</dt><dd>200 ₽</dd></div><div><dt>Доставка до терминала в Москве</dt><dd>1 800 ₽ / партия</dd></div></dl><p>${sales.wholesale.carrier}</p><a class="text-link" href="mailto:${sales.email}?subject=${encodeURIComponent('Оптовый заказ')}">Отправить оптовую заявку ${icon('mail')}</a></article><article class="sales-card" id="retail"><div class="eyebrow"><span>Для себя</span> РОЗНИЧНЫЕ ПРОДАЖИ</div><h2>Розничные продажи</h2><a class="sales-phone" href="tel:+79258809539">${sales.retailPhone}</a><h3>Покупка и самовывоз</h3><p>${sales.retail.showroom}</p><p>${sales.retailHours}.</p><p class="visit-callout">Обязательно позвоните за 1 час до приезда.</p><h3>Курьерская доставка</h3><p>${sales.retail.courier}</p><p>${sales.retail.courierOrder}</p><h3>Отправка в другой город</h3><p>${sales.retail.regionalOrder}</p><p>${sales.retail.regionalPayment}</p><p class="quiet-note">Вес мольберта: ${sales.retail.weight}.</p><a class="text-link" href="mailto:${sales.email}?subject=${encodeURIComponent('Розничный заказ и доставка')}">Написать о розничном заказе ${icon('mail')}</a></article></div><p class="quiet-note sales-source">Наличие, комплектацию и стоимость доставки подтвердим при оформлении заказа.</p></section>`}
function contactsPageBody(){return `<section class="wrap contacts-page-map"><div class="contacts-hours"><div>${eyebrow('Офис, склад и производство','')}<p>${D.sales.address}. <strong>${D.sales.distanceFromMKAD}.</strong></p></div><div><span>Режим работы офиса и производства</span><strong>${D.sales.officeHours}</strong><span>Розничные визиты: ${D.sales.retailHours}.</span></div></div>${contactMapPanel()}</section><section class="wrap section directions-section">${heading('Как добраться','МАРШРУТ НА ПРОИЗВОДСТВО','От МКАД —<br> <em>до нашей проходной.</em>')}<ol class="route-steps">${D.sales.route.map((step,i)=>`<li><span>0${i+1}</span><p>${step}</p></li>`).join('')}</ol></section>${salesSections()}`}
function deliveryPageBody(){return `<section class="wrap delivery-overview"><p class="delivery-lead">Условия покупки, оплаты и получения оборудования — для организаций и частных заказчиков.</p><div class="delivery-methods"><a href="#retail">${icon('pin')}<h2>Самовывоз</h2><p>Офис и демонстрационный зал в Мытищах. Позвоните за час до визита.</p></a><a href="#retail">${icon('box')}<h2>Курьер</h2><p>Доставка по адресу. Стоимость зависит от района и габаритов оборудования.</p></a><a href="#wholesale">${icon('tools')}<h2>В регионы</h2><p>Отправка через транспортную компанию с терминалом в Москве.</p></a></div></section>${salesSections()}<section class="wrap payment-summary"><div>${eyebrow('Оплата','ПОД ВАШ ЗАКАЗ')}<h2>Оплата товара<br> <em>и перевозки.</em></h2></div><div><p>Для оптового заказа выставляем счёт и сообщаем дату поставки.</p><p>При розничной отправке в регион товар, упаковку и доставку до московского терминала оплачивают до отправки. Перевозку между терминалами и доставку до подъезда — по прибытии в город получателя.</p><p>Стоимость оборудования смотрите на странице <a href="${url('prices/')}">«Цены»</a>. Способ оплаты розничной покупки уточните у производителя.</p>${link('Контакты и маршрут','contacts/',true)}</div></section>`}
function contactMapPanel(){const address=D.sales.address;return `<div class="home-contacts-grid"><div class="home-contact-details"><h3>Связаться с производителем</h3><span class="contact-label">Розничные заказы</span><a href="tel:+79258809539">${D.sales.retailPhone}</a><span class="contact-label">Оптовые заказы</span><a href="tel:+79262119363">${D.sales.wholesalePhone}</a><a class="contact-email" href="mailto:${D.sales.email}">${D.sales.email}</a><div class="contact-address">${icon('pin')}<p>Московская область, г. Мытищи,<br> Проектируемый проезд 4530, строение 2.<br> Завод «СпецМашМонтаж».</p></div><p class="contact-visit">Офис: пн–пт, 08:00–17:00.<br> Розничные визиты: пн–пт, 08:00–16:00.<br> Суббота — по договорённости.</p><a class="btn btn-outline" target="_blank" rel="noopener" href="https://yandex.ru/maps/?text=${encodeURIComponent(address)}">Построить маршрут ${icon('arrow')}</a></div><div class="contact-map"><iframe src="https://yandex.ru/map-widget/v1/?ll=37.761421%2C55.939803&pt=37.761421%2C55.939803%2Cpm2gnm&z=16" title="Карта: Мольберты.ру, Мытищи, проезд 4530, строение 2" loading="lazy" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe><a href="https://yandex.ru/maps/?text=${encodeURIComponent(address)}" target="_blank" rel="noopener">Открыть адрес в Яндекс Картах ↗</a></div></div>`}
const rubles=new Intl.NumberFormat('ru-RU');
function priceCell(value,from){return value===null?'<span class="no-price" aria-label="Цена в прайсе не указана">—</span>':`${from?'от ':''}${rubles.format(value)}`}
function priceItemName(item){const product=productById(D.priceProductLinks?.[item.id]);return product?`<a class="price-product-link" href="${url('product/'+product.id+'/')}">${esc(item.name)}</a>`:esc(item.name)}
function priceTables(sections){return sections.map(section=>`<section class="price-group" id="price-${section.id}"><div class="price-group-heading"><h2>${section.name}</h2></div><div class="price-table-scroll" tabindex="0" role="region" aria-label="Цены: ${section.name}"><table class="price-table"><caption class="sr-only">${section.name} — цены в рублях</caption><thead><tr><th scope="col">№</th><th scope="col">Наименование</th><th scope="col">Оптовая, ₽</th><th scope="col">Розничная, ₽</th></tr></thead><tbody>${section.items.map(item=>`<tr data-price-id="${item.id}"><td>${item.number}</td><th scope="row"><span>${priceItemName(item)}</span>${item.type?`<small>${item.type}</small>`:''}</th><td>${priceCell(item.wholesale,item.wholesaleFrom)}</td><td>${priceCell(item.retail,item.retailFrom)}</td></tr>`).join('')}</tbody></table></div></section>`).join('')}
function pricesPage(){const prices=D.prices;if(window.SITE_PRERENDER||!$('#price-results'))$('#prices').innerHTML=`<section class="wrap page-intro">${bread('Цены')}${eyebrow('Прайс-лист','')}<h1>Цены на мольберты и оборудование</h1><p>Оптовые и розничные цены на мольберты, оборудование для изостудий и принадлежности.</p><a class="btn btn-outline" href="${url(prices.sourceFile)}" download="Praiss_total_2026.pdf">Скачать прайс-лист PDF ${icon('download')}</a></section><section class="wrap prices-page"><div class="prices-toolbar"><label class="search-field">${icon('search')}<input id="price-search" type="search" placeholder="Название, формат или материал" aria-label="Поиск по прайс-листу"></label><label><span class="sr-only">Раздел прайса</span><select id="price-category"><option value="">Все разделы</option>${prices.sections.map(section=>`<option value="${section.id}">${section.name}</option>`).join('')}</select></label><button id="price-reset" class="text-link">Сбросить</button></div><nav class="price-group-links" aria-label="Разделы прайс-листа">${prices.sections.map(section=>`<a href="#price-${section.id}" data-price-section="${section.id}">${section.name}</a>`).join('')}</nav><div id="price-results" aria-live="polite">${priceTables(prices.sections)}</div><div class="prices-bottom">${link('Доставка и оплата','delivery/',true)}</div></section>${cta()}`;
 function filterPrices(){const query=$('#price-search').value.toLocaleLowerCase('ru').trim(),group=$('#price-category').value;const sections=prices.sections.filter(section=>!group||section.id===group).map(section=>({...section,items:section.items.filter(item=>(item.name+' '+(item.type||'')).toLocaleLowerCase('ru').includes(query))})).filter(section=>section.items.length);const count=sections.reduce((sum,section)=>sum+section.items.length,0);$('#price-results').innerHTML=count?priceTables(sections):'<div class="empty"><h2>Таких позиций не найдено</h2><p>Попробуйте другое название или сбросьте фильтры.</p></div>'}
 $('#price-search').addEventListener('input',filterPrices);$('#price-category').addEventListener('change',filterPrices);$('#price-reset').addEventListener('click',()=>{$('#price-search').value='';$('#price-category').value='';filterPrices()});document.querySelectorAll('[data-price-section]').forEach(a=>a.addEventListener('click',()=>{$('#price-search').value='';$('#price-category').value='';filterPrices()}));if(!$('#price-results').children.length||$('#price-search').value||$('#price-category').value)filterPrices();}
if($('#prices'))pricesPage();

function articleModelImages(ids){return `<div class="article-model-gallery">${ids.map(id=>{const p=productById(id);return `<div class="article-model-image"><button class="article-image-button" data-image="${esc(p.image)}" data-caption="${esc(p.name)}" aria-label="Увеличить: ${esc(p.name)}"><img src="${asset(p.image)}" alt="${esc(p.name)}" title="${esc(p.name)}" width="420" height="560" loading="lazy"></button><span class="article-model-caption">${esc(p.name)}</span></div>`}).join('')}</div>`}
function businessDocumentsBody(){const d=D.businessDocuments;return `<section class="wrap business-documents"><p class="documents-lead">${esc(d.lead)}</p><div class="business-downloads">${d.downloads.map(doc=>`<a class="business-download" href="${asset(doc.file)}" download>${icon('download')}<div><strong>${esc(doc.title)}</strong><p>${esc(doc.description)}</p><span>Скачать PDF · ${Math.ceil(doc.bytes/1024)} КБ</span></div>${icon('arrow')}</a>`).join('')}</div><section class="requisites-section"><h2>Реквизиты производителя</h2><dl class="company-requisites">${d.requisites.map(([label,value])=>`<div><dt>${esc(label)}</dt><dd>${esc(value)}</dd></div>`).join('')}</dl></section></section>`}

// Logo proposals are opt-in; the approved logo remains the default on every page.
(function maybeLoadLogoReview(){
 if(window.SITE_PRERENDER)return;
 const query=new URLSearchParams(location.search);let enabled=query.get('logo-preview')==='1';
 try{if(query.get('logo-preview')==='0')sessionStorage.removeItem('molberty-logo-review');else enabled=enabled||!!JSON.parse(sessionStorage.getItem('molberty-logo-review')||'null')?.active}catch{}
 if(!enabled)return;
 const script=document.createElement('script');script.src=asset('logo-preview.js');document.head.appendChild(script);
})();
